import JSConfetti from "js-confetti";
// Vite handles CSS imported from TypeScript, and hot reloads it.
import "./style.css";

const confetti = new JSConfetti();

const root = document.getElementById("root");
if (root === null) {
  throw new Error("Could not find #root");
}

// The compiled Elm code is loaded in a separate script tag, which creates
// `window.Elm`. See: https://lydell.github.io/elm-watch/window.Elm/
// The types for it (in ts/elm.d.ts) are generated by elm-watch.mts, using
// elm-ts-types. They know about the flags and ports of the Elm app.
const app = window.Elm.Main.init({ node: root });

// elm-ts-types nudges you into using `async` functions for port subscriptions:
// https://github.com/lydell/elm-ts-types#why-return-promisevoid-when-subscribing-to-ports
app.ports.celebrate.subscribe(async (count) => {
  await confetti.addConfetti({
    emojis: count % 10 === 0 ? ["🌳", "🌲"] : ["🎉", "✨", "🌈"],
  });
});
